#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    int w = min(n, m);
    int h = max(n, m);
    int masks = 1 << w;
    int full = masks - 1;
    const int INF = 1e9;

    vector<int> bits(masks);
    for (int mask = 0; mask < masks; ++mask)
        bits[mask] = __builtin_popcount(mask);

    vector<int> dp(masks * masks, INF), nextDp(masks * masks, INF);

    for (int mask = 0; mask < masks; ++mask)
        dp[mask] = bits[mask];  // State (0, mask)

    for (int row = 1; row < h; ++row) {
        fill(nextDp.begin(), nextDp.end(), INF);

        for (int prev = 0; prev < masks; ++prev) {
            for (int cur = 0; cur < masks; ++cur) {
                int value = dp[prev * masks + cur];
                if (value == INF) continue;

                int covered = prev | cur | ((cur << 1) & full) | (cur >> 1);
                int required = full ^ (covered & full);

                for (int next = 0; next < masks; ++next) {
                    if ((next & required) != required) continue;
                    int &target = nextDp[cur * masks + next];
                    target = min(target, value + bits[next]);
                }
            }
        }

        dp.swap(nextDp);
    }

    int minimumOccupied = INF;

    for (int prev = 0; prev < masks; ++prev) {
        for (int cur = 0; cur < masks; ++cur) {
            int covered = prev | cur | ((cur << 1) & full) | (cur >> 1);
            if ((covered & full) == full)
                minimumOccupied = min(minimumOccupied, dp[prev * masks + cur]);
        }
    }

    cout << n * m - minimumOccupied << '\n';
    return 0;
}

#include <iostream>
#include <vector>
