#include <climits>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    int h = max(n, m);
    int w = min(n, m);
    int masks = 1 << w;
    int full = masks - 1;
    int states = masks * masks;
    const int INF = INT_MAX / 4;

    vector<int> horizontal(masks), bits(masks);
    for (int mask = 0; mask < masks; ++mask) {
        horizontal[mask] = (mask | (mask << 1) | (mask >> 1)) & full;
        bits[mask] = __builtin_popcount(mask);
    }

    vector<int> dp(states, INF), nextDp(states, INF);

    for (int selected = 0; selected < masks; ++selected) {
        int need = full & ~horizontal[selected];
        dp[selected * masks + need] = bits[selected];
    }

    for (int row = 1; row < h; ++row) {
        fill(nextDp.begin(), nextDp.end(), INF);

        for (int state = 0; state < states; ++state) {
            if (dp[state] == INF) continue;

            int previous = state / masks;
            int need = state % masks;

            for (int selected = 0; selected < masks; ++selected) {
                if ((selected & need) != need) continue;

                int newNeed = full & ~(horizontal[selected] | previous);
                int newState = selected * masks + newNeed;
                nextDp[newState] = min(nextDp[newState],
                                       dp[state] + bits[selected]);
            }
        }

        dp.swap(nextDp);
    }

    int minimumOccupied = INF;
    for (int selected = 0; selected < masks; ++selected) {
        minimumOccupied = min(minimumOccupied, dp[selected * masks]);
    }

    cout << n * m - minimumOccupied << '\n';
    return 0;
}

