        fill(nextDp.begin(), nextDp.end(), INF);

        for (int pp = 0; pp < states; ++pp) {
            for (int p = 0; p < states; ++p) {
                int currentCost = dp[pp * states + p];
                if (currentCost == INF) continue;

                for (int cur = 0; cur < states; ++cur) {
                    if ((cover[p] | pp | cur) == full) {
                        int &value = nextDp[p * states + cur];
                        value = min(value, currentCost + bits[cur]);
                    }
                }
            }
        }

        dp.swap(nextDp);
    }

    int minimumOccupied = INF;
    for (int pp = 0; pp < states; ++pp) {
        for (int p = 0; p < states; ++p) {
            if ((cover[p] | pp) == full)
